import assert from 'node:assert/strict';
import fs from 'node:fs';
import {chromium} from '../../.local/browser-test/node_modules/playwright-core/index.mjs';
const fixture=JSON.parse(process.env.COURSE_SETTINGS_FIXTURE);
const browser=await chromium.launch({executablePath:'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',headless:true});
const output=new URL('../../evidence/course-settings-20260915/',import.meta.url);fs.mkdirSync(output,{recursive:true});
const page=await browser.newPage({viewport:{width:1440,height:1100}});page.setDefaultTimeout(20000);
const duplicateKeys=[];page.on('console',message=>{if(message.text().includes('same key'))duplicateKeys.push(message.text());});
const writes=[];page.on('request',r=>{if(['PATCH','POST'].includes(r.method())&&r.url().includes('/class-sections/'))writes.push({path:new URL(r.url()).pathname,method:r.method(),body:r.postDataJSON(),key:r.headers()['idempotency-key']});});
let stage='LOGIN';
try{
 await page.goto('http://localhost:3306/');await page.locator('#login-account').fill(fixture.email);await page.locator('#login-password').fill(fixture.password);await page.getByRole('button',{name:'登录',exact:true}).click();
 const card=page.locator(`[data-class-section-id="${fixture.sectionId}"]`);
 const open=async()=>{await card.getByRole('button',{name:/进入课程/}).click();await page.getByText(/已发布：门槛/).waitFor();};
 await open();
 const dialog=page.getByRole('dialog'),windowSection=dialog.locator('section').filter({has:page.locator('#course-window-config-title')});
 stage='LOCKED_DATES';
 for(const date of await windowSection.locator('input[type=date]').all())assert.equal(await date.isDisabled(),true);
 assert.equal(await page.locator('#course-published-template').isDisabled(),true);
 stage='SAVE_AND_RELOAD';
 const times=windowSection.locator('input[type=time]');await times.nth(0).fill('08:10');await times.nth(1).fill('20:20');
 await page.getByRole('combobox',{name:'打卡状态',exact:true}).click();await page.getByRole('option',{name:'暂停全部打卡',exact:true}).click();
 for(const [id,value] of Object.entries({'course-minimum-minutes':'20','course-maximum-minutes':'70','course-weekly-limit':'4','course-daily-limit':'2','course-target-course-hours':'9','course-target-other-hours':'11'}))await page.locator('#'+id).fill(value);
 await page.getByRole('button',{name:'保存设置',exact:true}).click();await dialog.waitFor({state:'hidden'});
 assert.equal(writes.filter(w=>w.method==='PATCH').length,1);assert.equal(writes.filter(w=>w.path.endsWith('/v81-rules')).length,1);
 const patch=writes.find(w=>w.method==='PATCH');assert.deepEqual(Object.keys(patch.body).sort(),['checkInWindowMode','dailyEndTime','dailyStartTime','expectedVersion'].sort());
 await page.reload();await open();assert.equal(await times.nth(0).inputValue(),'08:10');assert.equal(await times.nth(1).inputValue(),'20:20');
 await page.getByRole('combobox',{name:'打卡状态',exact:true}).filter({hasText:'暂停全部打卡'}).waitFor();
 for(const [id,value] of Object.entries({'course-minimum-minutes':'20','course-maximum-minutes':'70','course-weekly-limit':'4','course-daily-limit':'2','course-target-course-hours':'9','course-target-other-hours':'11'}))assert.equal(await page.locator('#'+id).inputValue(),value);
 stage='CANCEL';await times.nth(0).fill('09:30');await dialog.getByRole('button',{name:'取消',exact:true}).last().click();await open();assert.equal(await times.nth(0).inputValue(),'08:10');
 stage='INVALID_TIME';await times.nth(0).fill('22:00');const count=writes.length;await page.getByRole('button',{name:'保存设置',exact:true}).click();await page.getByText('每日结束时间必须晚于开始时间。',{exact:true}).first().waitFor();assert.equal(writes.length,count);await times.nth(0).fill('08:10');
 stage='PARTIAL_FAILURE_AND_RETRY';let rejected=false;await page.route('**/v81-rules',async route=>{if(route.request().method()==='POST'&&!rejected){rejected=true;await route.fulfill({status:503,contentType:'application/json',body:JSON.stringify({code:'SERVICE_UNAVAILABLE',message:'Synthetic transient failure'})});}else await route.continue();});
 await page.getByRole('combobox',{name:'打卡状态',exact:true}).click();await page.getByRole('option',{name:'允许打卡',exact:true}).click();
 const patchBefore=writes.filter(w=>w.method==='PATCH').length;await page.getByRole('button',{name:'保存设置',exact:true}).click();await page.getByText('课程设置未全部确认保存。每日时间可能已保存，请核对后重试。',{exact:true}).first().waitFor();
 assert.equal(await dialog.isVisible(),true);await page.getByRole('button',{name:'保存设置',exact:true}).click();await dialog.waitFor({state:'hidden'});
 assert.equal(writes.filter(w=>w.method==='PATCH').length,patchBefore+1);
 const ruleWrites=writes.filter(w=>w.path.endsWith('/v81-rules'));assert.equal(ruleWrites.at(-1).key,ruleWrites.at(-2).key);
 await page.unroute('**/v81-rules');await page.reload();await open();await page.getByRole('combobox',{name:'打卡状态',exact:true}).filter({hasText:'允许打卡'}).waitFor();
 stage='RULES_ONLY';const unchangedPatches=writes.filter(w=>w.method==='PATCH').length;await page.locator('#course-maximum-minutes').fill('71');await page.getByRole('button',{name:'保存设置',exact:true}).click();await dialog.waitFor({state:'hidden'});assert.equal(writes.filter(w=>w.method==='PATCH').length,unchangedPatches);await page.reload();await open();assert.equal(await page.locator('#course-maximum-minutes').inputValue(),'71');
 stage='OTHER_BUTTONS';const history=page.getByRole('region',{name:'历史补卡设置'});await history.getByRole('switch').check();await history.getByRole('button',{name:'保存补卡设置'}).click();await history.getByText('历史补卡范围已保存。',{exact:true}).waitFor();
 const settlement=page.getByRole('region',{name:'课程结算'});await settlement.getByRole('button',{name:'检查结算条件'}).click();await settlement.getByRole('button',{name:'检查结算条件'}).waitFor();assert.equal(await settlement.getByRole('button',{name:'确认课程结算'}).isDisabled(),true);
 const deletion=page.getByRole('region',{name:'删除课程'});await deletion.getByRole('button',{name:'删除课程',exact:true}).click();assert.equal(await deletion.getByRole('button',{name:'确认删除课程',exact:true}).isDisabled(),true);await deletion.getByRole('button',{name:'取消',exact:true}).click();
 await windowSection.screenshot({path:new URL('window-saved.png',output).pathname.replace(/^\/([A-Z]:)/,'$1')});
 assert.deepEqual(duplicateKeys,[]);
 console.log(JSON.stringify({check:'COURSE_SETTINGS_BROWSER',result:'PASS',checks:['locked dates','all editable fields persist after reload','cancel','invalid time','partial failure and idempotent retry','pause and resume','history save','settlement check','delete confirmation cancel']}));
}catch(error){console.log(JSON.stringify({stage,error:String(error),alerts:await page.getByRole('alert').allTextContents()}));throw error;}finally{await browser.close();}
